// Logger có cấu trúc: mỗi dòng là MỘT JSON, máy đọc/lọc/tổng hợp được
const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
function makeLogger(minLevel, base = {}, sink = console.log) {
  const log = (level, msg, extra) => {
    if (LEVELS[level] < LEVELS[minLevel]) return;
    sink(JSON.stringify({ level, msg, ...base, ...extra }));
  };
  return {
    debug: (m, e) => log("debug", m, e), info: (m, e) => log("info", m, e),
    warn: (m, e) => log("warn", m, e), error: (m, e) => log("error", m, e),
    child: (more) => makeLogger(minLevel, { ...base, ...more }, sink),   // thêm ngữ cảnh (requestId)
  };
}

const root = makeLogger("info", { service: "api" });
const req = root.child({ requestId: "r-1" });
root.debug("bị lọc");                    // dưới mức info: không in
req.info("đã nhận yêu cầu", { path: "/x" });

