function redact(obj, keys) {
  return Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, keys.includes(k) ? "[REDACTED]" : v]));
}
console.log(JSON.stringify(redact({ user: "an", password: "123", token: "abc" }, ["password", "token"])));

